  if(!rows.length)return panel(all.length?'Nenhum código neste filtro':'Confronto aguardando dados','<p>'+esc(date(day))+': '+(all.length?'Revise o filtro de produto.':'Envie as duas posições completas da mesma data. Nenhum total será calculado sem a base correspondente.')+'</p>')+pending+referenceModels();
  const provided=official.length&&!official[0]?.origem?.calculado,filiais=[...new Set(data.estoque.filter(x=>x.data===day&&x.sistema==='Premier').map(x=>x.filial))].sort(),total=official[0]?.origem?.total_informado;
  const reading=x=>Math.abs(x.diferenca)<=.00001?'Sem diferença numérica':x.diferenca>0?'Serbom acima do ERP':'Serbom abaixo do ERP';
  const intro=panel('Como entender Serbom × Premier','<div class="ct-reading"><div><b>Serbom</b><p>Base física conforme o modelo oficial. Nos confrontos calculados das posições: peso bruto disponível; quantidades bloqueadas ficam fora desta base.</p></div><div><b>Premier</b><p>Base Premier conforme o confronto recebido; nos calculados, disponível do ERP no alcance do relatório oficial'+(filiais.length?' · filiais '+esc(filiais.join(' e ')):'')+'. Não é o saldo físico somado novamente.</p></div></div><div class="ct-formula">Diferença do modelo = Serbom − Premier</div><p class="sub"><b>Positiva:</b> Serbom acima do ERP. <b>Negativa:</b> Serbom abaixo do ERP. <b>Zero:</b> sem diferença numérica. '+esc(date(day))+' · '+(provided?'Confronto oficial fornecido.':'Confronto calculado das posições oficiais.')+'</p><p class="sub">'+esc(official[0]?.metodo||'Regra das posições: Premier disponível; Serbom peso bruto disponível.')+'  Embalagem, unidade, filiais e cadastro precisam ser conferidos antes de concluir perda, falta ou sobra. Pacotes e peças não são convertidos em quilos.</p>');
