  const pairedRows=computed.length?rows.filter(x=>{const b=baseMap.get(x.sku);return b&&!/AUSENTE/.test(b.situacao);}):rows;

  const covered=rows.map(x=>baseMap.get(x.sku)).filter(Boolean),onlySerbom=covered.filter(x=>x.situacao==='AUSENTE NA PREMIER').length,onlyPremier=covered.filter(x=>x.situacao==='AUSENTE NA SERBOM').length,shared=covered.length-onlySerbom-onlyPremier;
  const coverage=covered.length?panel('Presença dos códigos nas posições recebidas',comparisonBars([{label:'Nas duas bases',value:shared},{label:'Somente Serbom',value:onlySerbom},{label:'Somente Premier',value:onlyPremier}],'Presença dos códigos nas duas posições da mesma data')+'<p class="sub">Contagem verificada nas posições da mesma data. Código ausente é diferente de código presente com saldo zero.</p>'):'';
