  const columns=['CÓDIGO / PRODUTO','UN. ERP','SERBOM','PREMIER','DIFERENÇA INFORMADA',...(stats.mismatch?['SERBOM − PREMIER']:[]),'INTERPRETAÇÃO','ORIGEM'];
