 function chart(points,label){if(!points.length)return '<p class="sub">Sem posições neste filtro.</p>';const max=Math.max(1,...points.map(p=>Math.abs(p.value)));return '<div class="ct-chart" role="img" aria-label="'+esc(label)+'">'+points.map(p=>'<div class="ct-column" title="'+esc(date(p.date)+': '+number(p.value))+'"><b>'+esc(number(p.value))+'</b><div style="height:'+Math.max(2,Math.abs(p.value)/max*135)+'px" class="ct-bar"></div><span>'+esc(date(p.date))+'</span></div>').join('')+'</div>';}
